// Limit array length:
if (variable.last200.length > 200) {
    variable.last200.splice(0,1);
}

/* WMA Calculator Function:
 * WMA: n == PERIODS ; p = price ; P1 == most recent
 *  ---------------------------------------------
 *  | P1 * n + P2 * (n-1) + P3 * (n-2) + ...    |
 *  |        /                                  |
 *  |   | n * (n+1) |                           |
 *  |   | /         |                           |
 *  |   | 2         |                           |
 *  ---------------------------------------------
*/
function WMA(prices, periods) {
    let pLen = prices.length;   // calculate once for speed.

    // Check we have enough values to make calculation:
    if (pLen < periods) { return 0; }

    let count = 1;
    let numerator = 0;
    for (let i = pLen - periods; i < pLen; i++, count++) {
        numerator += prices[i] * count;
    }
    return (numerator / ((periods * (periods + 1)) / 2));
}


/* Step 1 */
// wma1 = WMA(n/2) ; wma2 = WMA(n)
let wma1 = WMA(variable.last200, Math.round(variable.PERIODS / 2));
let wma2 = WMA(variable.last200, variable.PERIODS);

/* Step 2 */
let rawHMA = (2 * wma1) - wma2;
variable.rawHMAs.push(rawHMA);
// Limit array length:
if (variable.rawHMAs.length > 15) {
    variable.rawHMAs.splice(0, 1);
}

/* Step 3 */
variable.hma = WMA(variable.rawHMAs, Math.round(Math.sqrt(variable.PERIODS)));

/* Initialization Code */
// !Note! Update 'PERIODS' to change length.
variable.last200 = []
variable.rawHMAs = []
variable.PERIODS = 60;
if (parameters.periods !== undefined) {
    variable.PERIODS = parameters.periods;
}

/* NOTES:
HMA = WMA(sqrt(n)) of Raw HMA   ;   HMA= WMA(2*WMA(n/2) − WMA(n)),sqrt(n))
*/

/* Loop Code: */
let candle = record.current;

if (variable.closePrev == undefined) {
    variable.closePrev = candle.close;
}

let trueRange = (variable.closePrev == undefined) ?
                (candle.max - candle.min) :
                Math.max(
                    Math.max((candle.max - candle.min), Math.abs(candle.max - variable.closePrev)),
                    Math.abs(candle.min - variable.closePrev)
                );

// rma Calculation:
let rma = function(src, len) {
    let alpha = 1 / len;
    let sum = (variable.sumPrev === 0) ?
                src :
                alpha * src + (1 - alpha) * variable.sumPrev;
    variable.sumPrev = sum;
    return sum;
}

variable.atr = rma(trueRange, variable.PERIODS);
variable.atrPrev = variable.atr;
variable.closePrev = candle.close;

variable.tp1Up = variable.atr * variable.TPMULT + candle.close;
variable.tp2Up = 2 * variable.atr * variable.TPMULT + candle.close;
variable.tp3Up = 3 * variable.atr * variable.TPMULT + candle.close;
variable.tp1Down = candle.close - (variable.atr * variable.TPMULT);
variable.tp2Down = candle.close - (2 * variable.atr * variable.TPMULT);
variable.tp3Down = candle.close - (3 * variable.atr * variable.TPMULT);
variable.slUp = candle.close - (variable.atr * variable.SLMULT);
variable.slDown = variable.atr * variable.SLMULT + candle.close;

/* Initialization Code: */
variable.PERIODS = 15;
variable.TPMULT = 1;    // Take profit multiplier. default = 100% of ATR.
variable.SLMULT = 1.5;  // Stop Loss multiplier. default = 150% of ATR.

variable.closePrev = undefined;
variable.atrPrev = undefined;
variable.atr = 0;
variable.sumPrev = 0;
if (parameters.periods !== undefined) {
    variable.PERIODS = parameters.periods;
}
if (parameters.tpMult !== undefined) {
    variable.TPMULT = parameters.tpMult;
}
if (parameters.slMult !== undefined) {
    variable.SLMULT = parameters.slMult;
}

/* Loop Code */
let candle = record.current

// Build arrays Max and Min

variable.lastHighs.push(candle.max)
variable.lastLows.push(candle.min)

// Keep the array the correct size

if (variable.lastHighs.length > variable.PERIODS) {
    variable.lastHighs.splice(0, 1)
}

if (variable.lastLows.length > variable.PERIODS) {
    variable.lastLows.splice(0, 1)
}

// Calculate indicator values

variable.hiHigh = calculateHigh(variable.lastHighs, variable.PERIODS) // higher highs
variable.loLow = calculateLow(variable.lastLows, variable.PERIODS)  // lower lows
variable.midPoint = (variable.hiHigh + variable.loLow) / 2    // Midpoint

function calculateHigh(array, length) {

    /* We check we have enough values to make the calculation */
    if (array.length < length) { return 0 }

    return Math.max(...array)
}

function calculateLow(array, length) {

    /* We check we have enough values to make the calculation */
    if (array.length < length) { return 0 }

    return Math.min(...array)
}
variable.closePrice = (candle.close < variable.midPoint) ? 0 : 1;

/* Initialization Code */
// !Note! Update 'periods' to change length.
variable.lastHighs = [];
variable.lastLows = [];
variable.PERIODS = 40;
